            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                x,y=q.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(x+dx,y+dy)
                    if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]==3 and z not in seen: seen.add(z); q.append(z)
            boxes.append((min(x for x,y in comp),max(x for x,y in comp),min(y for x,y in comp),max(y for x,y in comp)))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
